const state={health:100,stamina:100,berries:0,wood:0,xp:0,level:1,distance:0,quest:0,kills:0,hasSpear:false,attack:0,heavy:0,dash:0,jump:0,invuln:0,day:0,weather:0};
const SAVE_KEY='primal-island-save-v1';let coins=0,beginnerLuckEligible=true,beginnerLuckEndsAt=0;
function loadProgress(){try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(saved&&typeof saved==='object'){coins=Math.max(0,Number(saved.coins)||0);if(typeof saved.beginnerLuckEligible==='boolean')beginnerLuckEligible=saved.beginnerLuckEligible;beginnerLuckEndsAt=Math.max(0,Number(saved.beginnerLuckEndsAt)||0)}}catch(error){console.warn('Could not load the island save.',error)}}
function saveProgress(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({version:1,coins,beginnerLuckEligible,beginnerLuckEndsAt}))}catch(error){console.warn('Could not save island progress.',error)}}
function isBeginnerLuckActive(){return !beginnerLuckEligible&&beginnerLuckEndsAt>Date.now()}
function refreshWallet(){const count=$('#coin-count'),bonus=$('#coin-bonus'),pill=count.closest('.coin-pill');count.textContent=String(coins);if(isBeginnerLuckActive()){const seconds=Math.ceil((beginnerLuckEndsAt-Date.now())/1000);bonus.textContent=`2× · ${seconds}s`;pill.classList.add('bonus-active')}else{bonus.textContent=beginnerLuckEligible?'COINS':'COINS';pill.classList.remove('bonus-active');if(!beginnerLuckEligible&&beginnerLuckEndsAt){beginnerLuckEndsAt=0;saveProgress()}}}
function addCoins(base){const earned=Math.round(base*(isBeginnerLuckActive()?2:1));coins+=earned;saveProgress();refreshWallet();return earned}
loadProgress();

